function check(input, actual, expected) {
  const [edges] = input;
  const n = edges.length + 1;
  if (!Array.isArray(actual) || actual.length !== n) return false;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { graph[u].push(v); graph[v].push(u); }
  // Root the tree at 0; parents, depths and binary-lifting ancestors give any distance in O(log n).
  const parent = new Array(n).fill(0), depth = new Array(n).fill(-1), order = [0];
  depth[0] = 0;
  for (let h = 0; h < order.length; h++) for (const v of graph[order[h]]) if (depth[v] < 0) { depth[v] = depth[order[h]] + 1; parent[v] = order[h]; order.push(v); }
  const up = [parent];
  while ((1 << up.length) < n) { const prev = up[up.length - 1]; up.push(prev.map(p => prev[p])); }
  const lca = (a, b) => {
    if (depth[a] < depth[b]) [a, b] = [b, a];
    for (let j = up.length - 1; j >= 0; j--) if (depth[a] - (1 << j) >= depth[b]) a = up[j][a];
    if (a === b) return a;
    for (let j = up.length - 1; j >= 0; j--) if (up[j][a] !== up[j][b]) { a = up[j][a]; b = up[j][b]; }
    return parent[a];
  };
  const dist = (a, b) => depth[a] + depth[b] - 2 * depth[lca(a, b)];
  // Both ends of a longest path: the deepest node, then the node farthest from it.
  let endA = 0;
  for (let v = 0; v < n; v++) if (depth[v] > depth[endA]) endA = v;
  let endB = endA;
  for (let v = 0; v < n; v++) if (dist(endA, v) > dist(endA, endB)) endB = v;
  // nodes[i] must be as far from i as possible, and one of the two ends always is.
  for (let i = 0; i < n; i++) {
    const x = actual[i];
    if (!Number.isInteger(x) || x < 0 || x >= n) return false;
    if (dist(i, x) !== Math.max(dist(i, endA), dist(i, endB))) return false;
  }
  return true;
}

