function validate([edges]) {
  const n = edges.length + 1;
  if (n < 2 || n > 100000) return 'The tree has 2 to 100,000 nodes, so edges holds 1 to 99,999 pairs.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (u < 0 || u >= n || v < 0 || v >= n) return 'Edge ends are nodes 0 to n - 1, where n = edges.length + 1.';
    const a = find(u), b = find(v);
    if (a === b) return 'The edges must form a tree: no cycles, self-loops or repeated edges.';
    root[a] = b;
  }
  return null;
}

