function lastMarkedNodes(edges) {
  const n = edges.length + 1;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    graph[u].push(v);
    graph[v].push(u);
  }

  // Iterative depth-first search: every node's distance from start.
  const distancesFrom = (start) => {
    const dist = new Array(n).fill(-1);
    dist[start] = 0;
    const stack = [start];
    while (stack.length > 0) {
      const node = stack.pop();
      for (const next of graph[node]) {
        if (dist[next] === -1) {
          dist[next] = dist[node] + 1;
          stack.push(next);
        }
      }
    }
    return dist;
  };

  // The node with the largest distance (the first one on a tie).
  const farthest = (dist) => {
    let best = 0;
    for (let node = 1; node < n; node++) {
      if (dist[node] > dist[best]) {
        best = node;
      }
    }
    return best;
  };

  // Two searches find both ends of a diameter (a longest path).
  const endA = farthest(distancesFrom(0));
  const distA = distancesFrom(endA);
  const endB = farthest(distA);
  const distB = distancesFrom(endB);

  // From every node, one of the two ends is a farthest node.
  const answer = [];
  for (let i = 0; i < n; i++) {
    answer.push(distA[i] > distB[i] ? endA : endB);
  }
  return answer;
}

