function lastMarkedNodes(edges) {
  const n = edges.length + 1;
  const neighbours = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { neighbours[u].push(v); neighbours[v].push(u); }
  const answer = [];
  // Simulate the marking second by second from each start and keep the final batch.
  for (let start = 0; start < n; start++) {
    const marked = new Set([start]);
    let lastBatch = [start];
    while (marked.size < n) {
      const batch = [];
      for (let v = 0; v < n; v++) if (!marked.has(v) && neighbours[v].some(u => marked.has(u))) batch.push(v);
      for (const v of batch) marked.add(v);
      lastBatch = batch;
    }
    answer.push(lastBatch[lastBatch.length - 1]);
  }
  return answer;
}

