function generate(rand, size) {
  const n = size === 'large' ? 2001 : 2 + Math.floor(rand() * 10);
  const shape = rand();
  const parent = [];
  for (let v = 1; v < n; v++) {
    if (shape < 0.2) parent.push(v - 1); // a path
    else if (shape < 0.35) parent.push(0); // a star
    else if (shape < 0.65) parent.push(Math.max(0, v - 1 - Math.floor(rand() * 3))); // long and thin
    else parent.push(Math.floor(rand() * v)); // random
  }
  // Relabel the nodes and shuffle the edges so that labels say nothing about the shape.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = parent.map((p, i) => rand() < 0.5 ? [label[p], label[i + 1]] : [label[i + 1], label[p]]);
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [edges];
}
